-- 0003: users, the current session, and the audit log (US-3, US-5).
--
-- Every table carries company_id with a foreign key to the one company row,
-- so no row can belong to another company (CO-3). Audit triggers for every
-- table are generated by the app (src/worker/audit.ts), not written here.

CREATE TABLE app_user (
  id         TEXT NOT NULL PRIMARY KEY,
  company_id TEXT NOT NULL REFERENCES company (id),
  name       TEXT NOT NULL CHECK (length(trim(name)) > 0),
  role       TEXT NOT NULL CHECK (role IN ('owner', 'bookkeeper')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

-- Exactly one owner per company (US-3)
CREATE UNIQUE INDEX app_user_one_owner ON app_user (company_id) WHERE role = 'owner';

-- Who is working right now. One row, set by the app at unlock; the audit
-- triggers read user_id from here. The keys are deferred because a new
-- company writes its session row before the company and user rows exist.
CREATE TABLE session (
  id          INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
  company_id  TEXT    NOT NULL REFERENCES company (id) DEFERRABLE INITIALLY DEFERRED,
  user_id     TEXT    NOT NULL REFERENCES app_user (id) DEFERRABLE INITIALLY DEFERRED,
  unlocked_at TEXT    NOT NULL
) STRICT;

CREATE TABLE audit_event (
  id         INTEGER NOT NULL PRIMARY KEY,
  company_id TEXT    NOT NULL REFERENCES company (id) DEFERRABLE INITIALLY DEFERRED,
  at         TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  user_id    TEXT,   -- from the session row; NULL only for rows written before any session existed
  action     TEXT    NOT NULL CHECK (action IN (
               'insert', 'update', 'delete',                -- row changes, from the generated triggers
               'create_company', 'unlock', 'lock',          -- written by the app
               'restore', 'schema_upgrade', 'passphrase_change')),
  entity     TEXT,   -- table name for row changes
  entity_id  TEXT,
  before     TEXT    CHECK (before IS NULL OR json_valid(before)),
  after      TEXT    CHECK (after IS NULL OR json_valid(after)),
  note       TEXT
) STRICT;

CREATE INDEX audit_event_at ON audit_event (at);
CREATE INDEX audit_event_entity ON audit_event (entity, entity_id);

-- The audit log is append-only (US-5)
CREATE TRIGGER audit_event_no_update
BEFORE UPDATE ON audit_event
BEGIN
  SELECT RAISE(ABORT, 'US-5: the audit log cannot be changed');
END;

CREATE TRIGGER audit_event_no_delete
BEFORE DELETE ON audit_event
BEGIN
  SELECT RAISE(ABORT, 'US-5: the audit log cannot be changed');
END;
